from time import sleep
import threading

def print_dots(num_dots):
    for _ in range(num_dots):
        print(".", end="")
        sleep(1)
    return True

def run_thread():
    return threading.Thread(target=print_dots, args=(10,))

t = run_thread()
t.start()

print("Hello!")
t.join()

