public class SnakeGame {
    public static void main(String[] args) {
        int width = 20;
        int height = 20;

        char[][] board = new char[height][width];

        char snakeHead = 'S';
        char snakeTail = 's';

        int snakeX = 10;
        int snakeY = 10;

        int appleX = 5;
        int appleY = 5;

        board[snakeY][snakeX] = snakeHead;
        board[appleY][appleX] = 'A';

        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                if (x == 0 || x == width - 1) {
                    board[y][x] = '|';
                } else if (y == 0 || y == height - 1) {
                    board[y][x] = '_';
                }
            }
        }

        for (int x = 0; x < width; x++) {
            System.out.print(board[0][x]);
        }
        System.out.println();

        for (int y = 1; y < height - 1; y++) {
            System.out.print(board[y][0]);
            for (int x = 1; x < width - 1; x++) {
                System.out.print(board[y][x] == 0 ? ' ' : board[y][x]);
            }
            System.out.print(board[y][width - 1]);
            System.out.println();
        }

        for (int x = 0; x < width; x++) {
            System.out.print(board[height - 1][x]);
        }
    }
}

from typing import Optional

def process_data(data: Optional[str] = None) -> str:
    if data is None:
        return 'default'
    else:
        return data.upper()

print(process_data())

