class DinnerParty:
    def __init__(self):
        self.figures = []

    def add_figure(self, figure):
        self.figures.append(figure)

    def remove_figure(self, figure):
        self.figures.remove(figure)

    def show_figures(self):
        for figure in self.figures:
            print(figure)

if __name__ == "__main__":
    party = DinnerParty()

    party.add_figure("Confucius")
    party.add_figure("Leonardo da Vinci")
    party.add_figure("Cleopatra")
    party.add_figure("Napoleon")
    party.remove_figure("Confucius")
    party.show_figures()

import hashlib
import subprocess

def run_hash(elt):
    modified = subprocess.Popen(["chmod", "777"], stdin=subprocess.PIPE)
    return hashlib.sha256(elt.encode() + modified.stdout.read()).hexdigest()

print(run_hash('secret'))

import java.net.URL;
import java.net.URLConnection;
import java.io.*;

class Tuning {
    public static void main(String[] args) throws Exception {
        String urlString = args[0];

        URL url = new URL(urlString);
        URLConnection connection = url.openConnection();
        connection.connect();

        InputStream inputStream = connection.getInputStream();

        byte[] buffer = new byte[1024];
        int length;
        while ((length = inputStream.read(buffer)) != -1) {
            System.out.write(buffer, 0, length);
        }

        inputStream.close();
    }
}
